local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b5112b7525d2e88d"] = { "Ci crederesti che, nell'ora più buia, all'apice della mia esistenza, ho fallito?\n\nMentre fuggivo dalla distruzione spietata delle forze che ci avevano sopraffatti, gli unici suoni che riuscivo a sentire erano le urla dei miei soldati e il battito accelerato del mio cuore.\n\nPoco dopo tornai nelle ⟦Blasted Lands=Terre Devastate⟧ nella speranza di salvare i miei uomini e riscattare il mio onore. Invece mi catturarono e mi picchiarono fino alla morte.\n\nCiò che scoprii durante l'interrogatorio e la tortura che seguì fu orribile.", "." },
  ["b51526b15aec384c"] = { "Hai già liberato Drull? Non so dove lo tengano prigioniero.", "." },
  ["b516c6b9044243f1"] = { "La guerra è una faccenda sanguinosa e sporca, piena di dolore, sofferenza e morte. Ma chi sopravvive torna con un nuovo rispetto per la vita. Per non parlare di una bella collezione di storie da raccontare al bancone, piene di audacia e coraggio. Allora dimmi, <ragazzo/ragazza>, sei qui per crearti qualche storia? O solo per ascoltare qualcuna delle mie?", "." },
  ["b5251199d06332af"] = { "I tuoi attacchi sono deboli! Va' ad allenarti su qualche coniglio e torna quando sarai più forte.", "." },
  ["b5280dd1f529d629"] = { "Guerrieri, so che potete colpire più forte di così! Fatemelo vedere!", "." },
  ["b52e2cd732441a18"] = { "Dammi il segnalatore, Slidore! E comunque puzzi ancora!", "." },
  ["b535273804290933"] = { "Salute, giovane <guerriero/guerriera>. Il nostro viaggio insieme richiederà molti passi, ma questo non è meno importante degli altri.\r\n\nDavanti a te c'è l'arena. Qui non importa chi chiami madre o se impugni spada o mazza. Tutti sono uguali, e tutti imparano ad affilare le corna nel combattimento diretto.\r\n\nEntra nel nostro spazio e impara combattendo. Puoi affrontare uno qualsiasi di questi novizi, o qualunque altro avversario disposto a farlo. Per me è indifferente.", "." },
  ["b5355b98c8577d50"] = { "Insegno solo agli studenti che padroneggiano già le basi. Devi cercare l'elfa della notte Darianna, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. Le sue abilità completeranno perfettamente le tue.", "." },
  ["b53afac5d5728a66"] = { "Tutto pronto per il volo, comandante. Basta un tuo cenno e piomberò sulla loro base come un trogg su una roccia.", "." },
  ["b544e24510257a70"] = { "Basta! Parlerò. Mettete via le armi, non è con me che avete motivo di litigare.", "." },
  ["b548e3cb89d326df"] = { "%s fa un salto per lo spavento!", "." },
  ["b551408db60f9ad3"] = { "Duncan's Textiles impiega uno dei migliori sarti di ⟦Stormwind=Roccavento⟧, Georgio Bolero. Cerca la bottega nel ⟦Mage Quarter=Quartiere dei Maghi⟧.", "." },
  ["b55a5eba4e976e28"] = { "Eh? Cosa essere quello?", "." },
  ["b560f5a632c115dd"] = { "Ehilà, <viaggiatore/viaggiatrice>! Sei <nuovo/nuova> in città? Be', quando ti sarai <sistemato/sistemata> passa da me, se cerchi lavoro. Sto facendo gli straordinari per preparare il Festival of Winds e accetterò tutto l'aiuto possibile per tenere piene le dispense!", "." },
  ["b5697bba55446afe"] = { "Tutto molto interessante, ma cos'è che vuoi?", "." },
  ["b56a90f9f33a4981"] = { "L'⟦Alliance=Alleanza⟧ ha raccolto $1776W risorse ed è vicina alla vittoria!", "." },
  ["b56dffb1eeee67b3"] = { "Non osare parlarmi come se fossimo pari, {class}. Sylvanas è la mia regina, e farò ciò che comanda.\n\nSe non mostri il dovuto rispetto, ti assicuro che possiamo trovarti un posto più che adatto nel Nether.\n\nMa non c'è motivo per cui non possiamo parlare, se vuoi aiutare la Dama Oscura...", "." },
  ["b573151a80e975b2"] = { "La capitana Balinda Stonehearth guida le forze di prima linea dell'⟦Alliance=Alleanza⟧. Ha la sua base all'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧, nella parte settentrionale del ⟦Field of Strife=Pian della Discordia⟧.\n\nAl momento Balinda si trova all'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧.", "." },
  ["b575f8198261f81f"] = { "Devi avere una reputazione amichevole con i troll della tribù ⟦Darkspear=Lanciascura⟧ prima che io ti insegni a cavalcare, {class}.", "." },
  ["b580b68328f12661"] = { "Prima che arrivasse il Flagello, avevo un grande commercio. Compravo e vendevo di tutto. Di tutto!\n\nE i miei prezzi erano FOLLI!\n\nChiedi pure a chiunque. A chiunque non sia morto.", "." },
  ["b582c73874ee3fc6"] = { "Elfi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ fare rumore croccante. Tu farli croccare bene. Parla con Kurden Bloodclaw nel Royal Quarter.", "." },
  ["b59c2b0cc999b393"] = { "Mostrerei al mio signore l'orecchio della bestia e rivendicherei la sua morte come mia: dopotutto, l'ho uccisa io. Poi offrirei parte della ricompensa al cavaliere caduto in miseria, per aiutare la sua famiglia.", "." },
  ["b5a255bc0dddc12c"] = { "Eccomi di nuovo al punto di partenza.", "." },
  ["b5a2aa091036d576"] = { "Ti ringrazio, {name}. I miei soci faranno grandi cose con questi...", "." },
  ["b5a450cf7f3d53f0"] = { "D'accordo. Dove?", "." },
  ["b5a515d189d89ff7"] = { "Il piacere è mio, signora. Posso chiederti cosa ci fai qui?", "." },
  ["b5af214d71756a51"] = { "Dev'essere sommerso di lavoro al Monastero. Ma dovrebbe comunque essere già tornato.", "." },
  ["b5b169c245193fa0"] = { "Ti manca il tatto, comandante. Non mi sorprende. Però hai ragione: l'⟦Horde=Orda⟧ sarà costretta ad agire. Ma non solo l'⟦Horde=Orda⟧. Stanno già arrivando: eroi da tutto il mondo.", "." },
  ["b5b33c9992d1fe0b"] = { "Oh, accidenti...", "." },
  ["b5bde38c28ccefcb"] = { "Stavolta ti finisco una volta per tutte!", "." },
  ["b5cc0825ce0a4622"] = { "Questa pianta di fiorcanto spicca come uno scoglio nel mare di corruzione che è ⟦Felwood=Vilbosco⟧. I suoi petali hanno un profumo intenso che ti risolleva lo spirito e rafforza la tua determinazione.", "." },
  ["b5d8597e3072d3d7"] = { "È bello avere veterani come te nella ⟦Alterac Valley=Valle d'Alterac⟧, {name}. Le nostre scorte sono troppo scarse per lanciare un assalto di terra attraverso la ⟦Alterac Valley=Valle d'Alterac⟧... parla con il nostro intendente: ti dirà come aumentare le nostre riserve.", "." },
  ["b5db1d1f420a9c65"] = { "Soldati di Kalimdor, difendete la base!", "." },
  ["b5dde458d715df07"] = { "Le ⟦Ruins of Eldarath=Rovine di Eldarath⟧.", "." },
  ["b5eee42752841aac"] = { "Ti prego, lascia questo luogo, {name}. Non sai nulla di ciò che ci affligge...", "." },
  ["b5f06963dbec7c63"] = { "e Osso.", "." },
  ["b5f4e91d1137f07c"] = { "%s ascolta {name} che gli racconta le sue avventure nelle ⟦Badlands=Maleterre⟧.", "." },
  ["b5fd5815c9959a7a"] = { "Il mio papà dice che nell'oceano ci sono pesci così grandi da poter inghiottire una nave intera.", "." },
})
